use std::cell::RefCell;

fn main() {
    let cell = RefCell::new(vec![1, 2]);   // note: no mut
    cell.borrow_mut().push(3);
    println!("{:?} has {} items", cell.borrow(), cell.borrow().len());
}

// Output:
// [1, 2, 3] has 3 items

use std::cell::RefCell;

fn main() {
    let c = RefCell::new(5);
    let a = c.borrow_mut();
    let b = c.borrow_mut();   // panics: RefCell already borrowed
    println!("{} {}", a, b);
}

// What you would see (the program panics):
// The program stops here with a panic, and prints a message like this
// (the file name and numbers may differ):
//   thread 'main' panicked at src/main.rs:6:15:
//   RefCell already borrowed

use std::cell::RefCell;

fn main() {
    let c = RefCell::new(5);
    let reader = c.borrow();
    println!("while reading: {}", c.try_borrow_mut().is_err());
    drop(reader);
    println!("after dropping the reader: {}", c.try_borrow_mut().is_err());
}

// Output:
// while reading: true
// after dropping the reader: false

use std::cell::RefCell;
use std::rc::Rc;

struct Account {
    balance: i64,
}

fn main() {
    let account = Rc::new(RefCell::new(Account { balance: 100 }));
    let shop = Rc::clone(&account);
    let bank = Rc::clone(&account);

    shop.borrow_mut().balance -= 30;
    bank.borrow_mut().balance += 5;

    println!("balance = {}", account.borrow().balance);
}

// Output:
// balance = 75

use std::cell::Cell;
use std::rc::Rc;

fn main() {
    let hits = Cell::new(0);
    hits.set(hits.get() + 1);
    hits.set(hits.get() + 1);
    println!("hits = {}", hits.get());

    let strong = Rc::new(5);
    let weak = Rc::downgrade(&strong);
    println!("{:?}", weak.upgrade());
    drop(strong);
    println!("{:?}", weak.upgrade());
}

// Output:
// hits = 2
// Some(5)
// None

