use std::cell::RefCell;
use std::rc::Rc;

fn main() {
    let counter = Rc::new(RefCell::new(0));
    let other = Rc::clone(&counter);
    *other.borrow_mut() += 5;
    *counter.borrow_mut() += 10;
    println!("counter = {}", counter.borrow());
}
